#include "processing.h"


processing::processing(std::vector<t_securitydata>data)
{
	/*
	initialize class
	*/
    
    //separate stock price, percentage shares and eq shares from the original vector
	for (int i = 0; i < data.size(); i++) {
		for (int j = 0; j < sizeof(t_securitydata); j++) {
			if (j == 0) {
				m_price.push_back(data[i].price);
			}
			else if (j == 1) {
				m_perc_shares_out.push_back(data[i].price);
			}
			else if (j == 2) {
				m_eq_shares_out.push_back(data[i].price);
			}
		}
	}
}

processing::~processing()
{
	/*
	destructor
	return nothing
	*/
}


// index calculation method
double processing::calculateindex()
{
	/*
	recalculate the number of securities in the vectors
	after each adjustments there are N new numbers of securities
	*/
	security_numbers = m_price.size();
	double sum = 0;
	for (int i = 0; i < security_numbers; i++) {
		sum += m_price[i] * m_perc_shares_out[i] * m_eq_shares_out[i];
	}
	double divisor = 1000;
	index = sum/divisor;
	return index;
}


double processing::divisor()
{
	double divisor_history = 1000;
	return divisor_history;
}

package net.uyghurdev.uyghurepubreader.re;

import java.util.ArrayList;
import java.util.HashMap;

import android.app.Activity;
import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.BaseAdapter;
import android.widget.TextView;

public class FontAdapter extends BaseAdapter {

	private Activity activity;
	private ArrayList<HashMap<String,String>> map;
	private static LayoutInflater inflater = null;

	public FontAdapter(Activity a, ArrayList<HashMap<String,String>> fonts){

		activity = a;
		map = fonts;
		inflater = (LayoutInflater) activity
		.getSystemService(Context.LAYOUT_INFLATER_SERVICE);
	}

	@Override
	public int getCount() {
		// TODO Auto-generated method stub
		return map.size();
	}

	@Override
	public Object getItem(int arg0) {
		// TODO Auto-generated method stub
		return map.get(arg0);
	}

	@Override
	public long getItemId(int position) {
		// TODO Auto-generated method stub
		return position;
	}

	@Override
	public View getView(int position, View convertView, ViewGroup parent) {
		// TODO Auto-generated method stub
		View vi = convertView;
		if (convertView == null) {
			vi = inflater.inflate(R.layout.fontlist, null);
		}
		TextView color=(TextView)vi.findViewById(R.id.item);
		color.setText(map.get(position).get("fontName"));

		return vi;
	}

}

